<?php require 'app/init.php';require 'app/view.php';$q=trim($_GET['q']??'');$tab=$_GET['tab']??'para-ti';$sql='SELECT p.*,u.nombre,u.usuario,l.titulo AS libro,(SELECT COUNT(*) FROM reacciones r WHERE r.publicacion_id=p.id) likes,(SELECT COUNT(*) FROM comentarios c WHERE c.publicacion_id=p.id) comments FROM publicaciones p JOIN usuarios u ON u.id=p.usuario_id LEFT JOIN libros l ON l.id=p.libro_id';$args=[];if($q!==''){$sql.=' WHERE p.contenido LIKE ? OR p.titulo LIKE ? OR u.nombre LIKE ? OR l.titulo LIKE ?';$args=array_fill(0,4,'%'.$q.'%');}$sql.=$tab==='mas-leidos'?' ORDER BY likes DESC,p.creado_en DESC':' ORDER BY p.creado_en DESC';$sql.=' LIMIT 30';$st=db()->prepare($sql);$st->execute($args);top('Inicio');?><div class="layout"><?php sidebar();?><main><h1>Tu comunidad lectora</h1><div class="tabs"><a href="index.php?tab=para-ti">Para ti</a><a href="index.php?tab=mas-leidos">Más leídos</a><a href="clubes.php">Mis clubes</a></div><div class="card"><a href="publicar.php" class="field" style="display:block;color:#777">¿Qué te dejó tu última lectura?</a><div class="actions"><a href="publicar.php?tipo=resena">♧ Reseña</a><a href="publicar.php?tipo=frase">❞ Frase</a><a href="publicar.php?tipo=foto">▧ Foto</a></div></div><?php foreach($st as $p):?><article class="card"><div class="post-head"><div class="avatar"><?=e(mb_substr($p['nombre'],0,1))?></div><div><strong><?=e($p['nombre'])?></strong> <span class="muted">@<?=e($p['usuario'])?> · <?=e($p['creado_en'])?></span><br><span class="muted"><?=e(ucfirst($p['tipo']))?><?= $p['libro']?' · '.e($p['libro']):''?></span></div></div><?php if($p['titulo']):?><h2 class="post-title"><?=e($p['titulo'])?></h2><?php endif;?><div class="post-body"><?=e($p['contenido'])?></div><?php if($p['imagen']):?><img class="post-img" src="<?=e($p['imagen'])?>" alt="Imagen de publicación"><?php endif;?><div class="actions"><form method="post" action="accion.php"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button name="accion" value="like">♥ <?=$p['likes']?></button></form><a href="publicacion.php?id=<?=$p['id']?>">▢ <?=$p['comments']?> comentarios</a><form method="post" action="accion.php"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="secondary" name="accion" value="guardar">♧ Guardar</button></form></div></article><?php endforeach;?></main><?php rightbar();?></div><?php bottom();?>